// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 msgValue) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        // Set initial balance
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: initialBalance}("");
        require(ok, "funding failed");
        // record previous balance
        uint256 prevBalance = c.getBalance(caller);
        // attempt addToBalance
        vm.prank(caller);
        (bool reverted, ) = address(c).call{value: msgValue}(abi.encodeWithSignature("addToBalance()"));
        uint256 newBalance = c.getBalance(caller);
        // Rule: if no overflow, balance = prevBalance + msgValue; else unchanged
        if (!reverted) {
            assertTrue(newBalance == prevBalance + msgValue);
        } else {
            assertTrue(newBalance == prevBalance);
        }
    }
}

