pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr, uint256 initialBalance, uint256 msgValue) public {
        vm.assume(initialBalance <= type(uint256).max - msgValue);
        vm.assume(initialBalance > 0 || msgValue > 0);

        // Set up initial balance
        vm.deal(addr, initialBalance);

        // Fund the contract to allow withdrawal
        vm.deal(address(c), initialBalance + msgValue);

        // Give the address some balance in the contract
        vm.prank(address(0));
        (bool success, ) = address(c).call(abi.encodeWithSignature("addToBalance()"));
        vm.assume(success); // ensure initial deposit works

        // Now prank as addr and call addToBalance
        vm.prank(addr);
        bool reverted = false;
        try c.addToBalance{value: msgValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.getBalance(addr);

        // The rule: if it didn't revert, the balance should be initialBalance + msgValue (not multiplied)
        // If it reverted, balance should be unchanged
        assertTrue((!reverted && balanceAfter == initialBalance + msgValue) || (reverted && balanceAfter == initialBalance));
    }
}

