pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 amount) public {
        vm.assume(user != address(0) && user != address(c));
        amount = bound(amount, 1, 100 ether);

        // Record contract balance before
        uint256 contractBalanceBefore = address(c).balance;

        // User adds balance
        vm.deal(user, amount);
        vm.prank(user);
        c.addToBalance{value: amount}();

        // User withdraws
        vm.prank(user);
        c.withdrawBalance();

        // After withdraw, contract balance should be same as before (since all user balance returned)
        assertTrue(address(c).balance == contractBalanceBefore);
    }
}

