pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 amount) public {
        vm.assume(user != address(this) && user != address(0) && user != address(c));
        amount = bound(amount, 1, 1e18);
        vm.deal(user, amount);
        vm.prank(user);
        c.addToBalance{value: amount}();
        uint256 initialUserBalance = user.balance;
        uint256 initialContractBalance = address(c).balance;
        c.withdrawBalance();
        assertTrue(user.balance == initialUserBalance + amount && address(c).balance == initialContractBalance - amount);
    }
}
